#!/usr/bin/env python3
# read gradients from orca
import numpy as np

def get_Energy(name, search):
    with open('{}.out'.format(name)) as f:
        a = f.readlines()
        for i in a:
            if search in i:
                return(float(i.split(' \n')[0].split(' ')[-1]))

def orcaread(name):
    with open(name) as f:
        data = f.readlines()
    return data

def apprd(data, conv):
    # data and how to convert data (see blnso)
    il = []
    for i in data:
        j = i.split()
        if len(j) == 1:
            il.append(j[0])
        else:
            il.append(j)
    if len(il) == 1:
        il = il[0]
    return decapprd(il, conv)

def decapprd(data, n):
    # get data and n as key how to convert
    # for new case: create l = and cut data as u want. n == 0 case is not required
    # if n == 0: pass cause of previous formating
    if n == 1:
        l = int(data)
    if n == 2: 
        l = float(data)
    if n == 3: 
        l = []
        for i in data:
            l.append(float(i))
        l = np.asarray(l)
    if n == 4:
        l = []
        for i in range(len(data)):
            l.append(int(data[i][0]))
            for j in range(len(data[i])-1):
                l.append(float(data[i][j+1]))
        l = np.asarray(l)
    return np.asarray(l)
    

def parse_orca(name, breadl):
    try:
        data = getengrads(name, breadl)
    except Exception as e:
        data = {}

    for i in breadl:
        if i not in data.keys():
            try:
                data[i] = get_Energy(name, i)
            except:
                data[i] = ''
    return data

# name: finename (str), breadl: keys from blns to decode (list[str])
def getengrads(name, breadl):
    # blns[1] encoding: 0 = str, 1 = int, 2 = float, 3 = array of floats, 4 array [int, floats...]
    # feel free to add further cases to def decapprd note, that the std type is str
    blns = {'natoms': '# Number of atoms\n', 
            'total_energy': '# The current total energy in Eh\n',
            'gradient': '# The current gradient in Eh/bohr\n',
            'coordinates': '# The atomic numbers and current coordinates in Bohr\n'}
    blnso = {'# Number of atoms\n': ['natoms', 2], 
            '# The current total energy in Eh\n': ['total_energy', 2], 
            '# The current gradient in Eh/bohr\n': ['gradient', 3], 
            '# The atomic numbers and current coordinates in Bohr\n': ['coordinates', 4]}
    openname = '{}.engrad'.format(name)
    data = orcaread(openname)
    retl = {}
    blocks = []
    read = False
    i = 0
    start = 0
    while i < len(data):
        if data[i] in blnso.keys():
            if read == False:
                startkey = data[i]
                start = i
                read = True
                i += 1
            elif read == True:
                read = False
                end = i
                blocks.append([startkey, start, end])
        elif data[i] == '#\n':
            if read == True:
                read = False
                end = i
                blocks.append([startkey, start, end])
        i += 1 
    blocks.append([startkey, start, i])
    for i in blocks:
        retl[blnso[i[0]][0]] = apprd(data[i[1]+2:i[2]], blnso[i[0]][1])
    return retl
